// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Load font for the coordinate readout
const { fontFamily: interFamily } = loadInter();



export type ScreenshotToolProps = Record<string, any>;

const ScreenshotTool: React.FC<ScreenshotToolProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 3,
  dragWidth = 400,
  dragHeight = 300,
  startX = 576, // 30% of 1920
  startY = 378, // 35% of 1080
  dragDuration = 1.0,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Timing logic (in frames)
  const fadeInStart = 0;
  const fadeInEnd = 0.2 * fps;
  const dragStart = 0.4 * fps;
  const dragEnd = dragStart + dragDuration * fps;

  // Derive animation states from current frame
  const crosshairOpacity = interpolate(frame, [fadeInStart, fadeInEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const dragProgress = interpolate(frame, [dragStart, dragEnd], [0, 1], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate current dimensions and positions
  const currentWidth = dragWidth * dragProgress;
  const currentHeight = dragHeight * dragProgress;
  const currentX = startX + currentWidth;
  const currentY = startY + currentHeight;

  // Safe background parsing
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Selection Rectangle */}
      {currentWidth > 0 && currentHeight > 0 && (
        <div
          style={{
            position: "absolute",
            left: startX,
            top: startY,
            width: currentWidth,
            height: currentHeight,
            backgroundColor: "rgba(255, 255, 255, 0.1)",
            border: "1px solid rgba(255, 255, 255, 0.9)",
            boxSizing: "border-box",
            transition: "none",
            pointerEvents: "none",
          }}
        />
      )}

      {/* Crosshair Cursor */}
      <div
        style={{
          position: "absolute",
          left: currentX,
          top: currentY,
          width: 0,
          height: 0,
          opacity: crosshairOpacity,
          transition: "none",
          pointerEvents: "none",
        }}
      >
        {/* Black outline layers (slightly thicker to form an outline) */}
        <div
          style={{
            position: "absolute",
            width: 3,
            height: 25,
            left: -1,
            top: -12,
            backgroundColor: "#000",
            transition: "none",
          }}
        />
        <div
          style={{
            position: "absolute",
            width: 25,
            height: 3,
            left: -12,
            top: -1,
            backgroundColor: "#000",
            transition: "none",
          }}
        />

        {/* White inner layers */}
        <div
          style={{
            position: "absolute",
            width: 1,
            height: 23,
            left: 0,
            top: -11,
            backgroundColor: "#fff",
            transition: "none",
          }}
        />
        <div
          style={{
            position: "absolute",
            width: 23,
            height: 1,
            left: -11,
            top: 0,
            backgroundColor: "#fff",
            transition: "none",
          }}
        />

        {/* Live Coordinate Readout */}
        <div
          style={{
            position: "absolute",
            left: 15,
            top: 15,
            backgroundColor: "rgba(35, 35, 35, 0.75)",
            color: "#fff",
            fontFamily: interFamily,
            fontSize: 13,
            fontWeight: 400,
            padding: "3px 7px",
            borderRadius: 4,
            whiteSpace: "nowrap",
            boxShadow: "0 2px 8px rgba(0, 0, 0, 0.15)",
            border: "1px solid rgba(255, 255, 255, 0.1)",
            transition: "none",
          }}
        >
          {Math.round(currentWidth)} × {Math.round(currentHeight)}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ScreenshotTool;